def is_probable_prime(n: int) -> bool:
    """Trial division by 6k +/- 1; exact for 64-bit inputs but slow beyond ~10**12."""
    if n < 2:
        return False
    if n < 4:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    d: int = 5
    while d * d <= n:
        if n % d == 0 or n % (d + 2) == 0:
            return False
        d += 6
    return True

